True def transform(grid):
    out = [row[:] for row in grid]
    occupied = [i for i, row in enumerate(grid) if any(row)]
    if not occupied:
        return out
    top, bottom = min(occupied), max(occupied)
    for r in range(top + 1, bottom):
        if not any(grid[r]):
            out[r] = [3] * len(grid[r])
    return out
